SELECT DISTINCT md.chembl_id AS compound_chembl_id, cs.canonical_smiles FROM molecule_dictionary md JOIN activities act ON md.molregno = act.molregno JOIN assays a ON act.assay_id = a.assay_id JOIN target_dictionary td ON a.tid = td.tid JOIN compound_structures cs ON cs.molregno = md.molregno WHERE td.pref_name = 'lethal malignant brain tumor-like protein 1' AND td.organism = 'Homo sapiens' ORDER BY md.chembl_id
